// Which city, district or zone a postal pincode belongs to. Pure functions, no database: the Firestore reads stay in quote.ts /
// serviceRules.ts and hand their records in here.
//
// Why pincodes: a map pin or a Google result names the town it sits in ("Cumbum, Tamil Nadu 625516"), not the district an admin
// set up ("Theni"), and a city saved from the built-in list has no centre point to measure from. Every address carries a pincode,
// and India Post's directory says which district it is in (domain/pincodeCities.ts, generated by tools/build-pincodes.py).
import { PINCODES_BY_CITY } from './pincodeCities';

/** GST state codes, as stored in a rule's state scope by the admin page. */
export const STATE_NAMES: Record<string, string> = {
  '01': 'Jammu and Kashmir', '02': 'Himachal Pradesh', '03': 'Punjab', '04': 'Chandigarh', '05': 'Uttarakhand', '06': 'Haryana', '07': 'Delhi',
  '08': 'Rajasthan', '09': 'Uttar Pradesh', '10': 'Bihar', '11': 'Sikkim', '12': 'Arunachal Pradesh', '13': 'Nagaland', '14': 'Manipur',
  '15': 'Mizoram', '16': 'Tripura', '17': 'Meghalaya', '18': 'Assam', '19': 'West Bengal', '20': 'Jharkhand', '21': 'Odisha', '22': 'Chhattisgarh',
  '23': 'Madhya Pradesh', '24': 'Gujarat', '26': 'Dadra and Nagar Haveli and Daman and Diu', '27': 'Maharashtra', '29': 'Karnataka', '30': 'Goa',
  '31': 'Lakshadweep', '32': 'Kerala', '33': 'Tamil Nadu', '34': 'Puducherry', '35': 'Andaman and Nicobar Islands', '36': 'Telangana',
  '37': 'Andhra Pradesh', '38': 'Ladakh',
};
const low = (v: unknown) => (typeof v === 'string' ? v : '').trim().toLowerCase();
const CODE_OF_NAME = new Map(Object.entries(STATE_NAMES).map(([code, name]) => [name.toLowerCase(), code]));

/** The GST code of a state written as a code ("33") or a name ("Tamil Nadu"); '' when unknown. */
export function stateCodeOf(state: unknown): string {
  const v = typeof state === 'string' ? state.trim() : '';
  return /^\d{2}$/.test(v) ? v : CODE_OF_NAME.get(v.toLowerCase()) ?? '';
}

// The pincodes inside each city / district: city name -> GST state code -> pincodes.
let index: Map<string, Map<string, Set<string>>> | null = null;
function load(): Map<string, Map<string, Set<string>>> {
  if (index) return index;
  index = new Map();
  for (const [key, pins] of Object.entries(PINCODES_BY_CITY)) {
    const cut = key.indexOf('|');
    const city = key.slice(cut + 1);
    const byState = index.get(city) ?? new Map<string, Set<string>>();
    byState.set(key.slice(0, cut), new Set(pins.split(' ')));
    index.set(city, byState);
  }
  return index;
}

/**
 * The pincodes inside a city / district (India Post). With a state, only that state's city of that name; without one, every
 * state that has a city of that name. null when the directory has no such city.
 */
export function pinsOfCity(city: unknown, state?: unknown): Set<string> | null {
  const byState = load().get(low(city));
  if (!byState) return null;
  const hasState = typeof state === 'string' && state.trim() !== '';
  if (!hasState) return new Set([...byState.values()].flatMap((s) => [...s]));
  const code = stateCodeOf(state);
  return code ? byState.get(code) ?? null : null;
}

export interface PinCity { id: string; /** name and city as saved, any case */ names: string[]; state: string; /** pincodes saved on the record itself */ pincodes?: string[] }
export interface PinZone { id: string; parentId: string; pincodes: string[] }

/**
 * The City a pincode belongs to: a pincode saved on a City record first, else a City whose district / town list (India Post) holds it.
 * When several qualify the smallest list wins, so a town (Hosur) beats its district (Krishnagiri). null when none does.
 */
export function cityByPincode(pin: string, cities: readonly PinCity[]): string | null {
  if (!/^[1-9]\d{5}$/.test(pin)) return null;
  const hits: { id: string; size: number; saved: boolean }[] = [];
  for (const c of cities) {
    if (c.pincodes?.includes(pin)) { hits.push({ id: c.id, size: c.pincodes.length, saved: true }); continue; }
    for (const name of c.names) {
      const set = pinsOfCity(name, c.state);
      if (set?.has(pin)) { hits.push({ id: c.id, size: set.size, saved: false }); break; }
    }
  }
  hits.sort((a, b) => Number(b.saved) - Number(a.saved) || a.size - b.size || a.id.localeCompare(b.id));
  return hits[0]?.id ?? null;
}

/** The zone of a City that lists the pincode. Two zones never share one (the admin refuses it); if they do, the smaller zone wins. */
export function zoneByPincode(pin: string, zones: readonly PinZone[]): string | null {
  if (!/^[1-9]\d{5}$/.test(pin)) return null;
  const hits = zones.filter((z) => z.pincodes.includes(pin)).sort((a, b) => a.pincodes.length - b.pincodes.length || a.id.localeCompare(b.id));
  return hits[0]?.id ?? null;
}
